/// <summary>
/// This is a RDP class for the transfer order shipment.s
/// </summary>
[SRSReportParameterAttribute(classstr(METTransferOrderShippmentContract))]
class METTransferOrderShippmentDP extends SrsReportDataProviderBase
{
    METTransferOrderShipmentHeaderTmp header;
    METTransferOrderShipmentLineTmp line;
    InventTransferId transferId;
    #ISOCountryRegionCodes
    #PrintMgmtSetup

    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// Process report
/// </summary>
public void processReport()
{
    METTransferOrderShippmentContract contract = this.parmDataContract() as METTransferOrderShippmentContract;

    transferId = contract.parmTransferId();

    if (transferId)
    {
        this.insertHeaderData();
    }
}

/// <summary>
/// Inserts the report header data.
/// </summary>
public void insertHeaderData()
{
    const str TransShipment = 'Transfer order shipment document';
    const str ReturnPolicy  = 'Return policy';

    CompanyInfo         companyInfo = CompanyInfo::find();
    InventLocation      inventLocationTo, inventLocationFrom;
    METIndustryKeyTable industryKeyTable;
    InventTransferTable transferTableDp;
    InventTransferJour  inventTransferJour;

    select InventLocationIdTo, TransferId, InventLocationIdFrom from transferTableDp
        where transferTableDp.TransferId == transferId;

    //Get To warehouse details.
    select firstonly METWHSubEntity, Name, RecId from inventLocationTo
        where inventLocationTo.InventLocationId == transferTableDp.InventLocationIdTo;

    //Get From warehouse details.
    select firstonly METWHSubEntity, Name, RecId from inventLocationFrom
        where inventLocationFrom.InventLocationId == transferTableDp.InventLocationIdFrom
        join CompanyName, IndustryKey from industryKeyTable
        where industryKeyTable.IndustryKey == inventLocationFrom.METWHSubEntity;

    // Gets the Posting date from the transger order journals
    select firstonly RecId, TransDate from inventTransferJour
        where inventTransferJour.TransferId == transferId
        && inventTransferJour.UpdateType == InventTransferUpdateType::Shipment;

    header.clear();

    header.IndustryKey                  = industryKeyTable.IndustryKey;
    header.MetCashLogo                  = this.getCompanyLogo(companyInfo.METLegalEntityType, inventLocationTo.METWHSubEntity);
    header.Transferordershipdoc         = TransShipment;
    header.ToAddressName                = inventLocationTo.Name;
    header.ToWarehouseAddress           = this.getWareHousePrimaryAddress(inventLocationTo.RecId).Address;

    header.FromWarehouseAddress         = this.getWareHousePrimaryAddress(inventLocationFrom.RecId).Address;
    header.FromAddressName              = InventLocation::find(transferTableDp.InventLocationIdFrom).Name;

    header.TransferId                   = transferTableDp.TransferId;
    header.SpecialInstructions          = METInventTransferTableExt::findByTransferId(transferTableDp.TransferId).DeliveryInstructions;
    header.ReturnPolicy                 = ReturnPolicy;
    header.BundleReportHeaderGuidStr    = bundleHeaderReportGuid;
    header.ShipmentHeaderGuidStr        = headerReportGuid;
    header.PostingDate                  = inventTransferJour.RecId != 0 ? inventTransferJour.TransDate : header.PostingDate;

    header.insert();

    line.clear();
    this.insertLineData();
}

/// <summary>
///  Inserts the report line data.
/// </summary>
public void insertLineData()
{
    real                    cases = 0;
    Factor                  factor;
    InventDim               inventDimTO, inventDimDefaultSetting;
    InventTransferLine      transferLine;
    METInventTransferLine   metTransferLine;
    InventTable             inventTable;
    InventTableModule       inventTableSalesMod;
    InventItemSalesSetup    inventItemSalesSetup;
    InventItemGTIN          inventItemGTIN;
    InventItemBarcode       barcode;
    UnitOfMeasureFromRecId  fromUnit,toUnit;
    RecordInsertList        insertSet = new RecordInsertList(tableNum(METTransferOrderShipmentLineTmp), true, true, true, true, true, line);

    while select transferLine
        where transferLine.TransferId == transferId
            join metTransferLine
                where metTransferLine.InventTransferLine == transferLine.RecId
            join inventDimTO
                where inventDimTO.inventDimId == transferLine.InventDimId
            join inventTable
                where transferLine.ItemId == inventTable.ItemId
    {
        select firstonly ItemBarCode from barcode
            where barcode.itemId == transferLine.ItemId
            && barcode.UnitID == transferLine.UnitId;

        select firstonly METSalesUnit from inventItemSalesSetup
            join inventDimDefaultSetting
                where inventDimDefaultSetting.inventDimId == inventItemSalesSetup.InventDimId
                && inventItemSalesSetup.ItemId == inventTable.ItemId
                && inventDimDefaultSetting.InventSiteId == inventDimTO.InventSiteId;

        line.Cases = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(transferLine.ItemId,
                                                                                           transferLine.inventDimId,
                                                                                           transferLine.QtyShipped,
                                                                                           transferLine.UnitId,
                                                                                           inventItemSalesSetup.METSalesUnit);

        line.LineNum                    = transferLine.LineNum;
        line.ItemId                     = transferLine.ItemId;
        line.ItemName                   = inventTable.productName(SystemParameters::getSystemLanguageId());
        line.SalesUoM                   = inventItemSalesSetup.METSalesUnit;
        line.TotalEstimatedPallets      = this.CalculateEstimatedPalletsForTransferOrder(transferLine, line.Cases);
        line.GlobalTradeItemNumber      = barcode.itemBarCode;
        line.BundleReportHeaderGuidStr  = bundleHeaderReportGuid;
        line.ShipmentHeaderGuidStr      = headerReportGuid;
        insertSet.add(line);
    }
    insertSet.insertDatabase();
}

/// <summary>
/// dsHeader
/// </summary>
/// <returns>METTransferOrderShipmentHeaderTmp</returns>
[SRSReportDataSetAttribute(tableStr(METTransferOrderShipmentHeaderTmp))]
public METTransferOrderShipmentHeaderTmp dsHeader()
{
    select header;

    return header;
}

/// <summary>
/// dsLines
/// </summary>
/// <returns>METTransferOrderShipmentLineTmp</returns>
[SRSReportDataSetAttribute(tableStr(METTransferOrderShipmentLineTmp))]
public METTransferOrderShipmentLineTmp dsLines()
{
    select line;

    return line;
}

/// <summary>
/// Get METcash logo based on entity
/// </summary>
/// <param name = "_legalEntityType">LegalEntityType</param>
/// <param name = "_subEntityWareHouse">SubEntity warehouse</param>
/// <returns>Image</returns>
public container getCompanyLogo(METLegalEntityType _legalEntityType, InventLocationId _subEntityWareHouse)
{
    container image;

    switch (_legalEntityType)
    {
        case METLegalEntityType::Food:
            image = SysDocuBrandImages::getImage(_subEntityWareHouse);
            break;

        case METLegalEntityType::Liquor:
            image = SysDocuBrandImages::getImage(METConstants::LiquorLogo);
            break;

        default:
            break;

    }
    return image;
}

/// <summary>
/// Returns the total pallet valume.
/// </summary>
/// <param name = "_inventTransferLine">_inventTransferLine buffer</param>
/// <returns>The pallet volume</returns>
private real calculateEstimatedPalletsForTransferOrder(InventTransferLine _inventTransferLine, real _shippedQtyInCases)
{
    real                    totalPallet;
    METUOMVolume            volume;
    METWHSPhysDimUOMSite    metWHSPhysDimUOMSite;
    METInventLocation       metInventLocation;
    InventLocation          inventLocation;
    InventTransferTable     inventTransferTable;

    InventSiteId inventSiteIdFrom = InventLocation::find(_inventTransferLine.inventTransferTable().InventLocationIdFrom).InventSiteId;

    select firstonly WHSPalletVolume from metInventLocation
        exists join inventLocation
            where metInventLocation.InventLocation == inventLocation.RecId
        exists join inventTransferTable
            where inventTransferTable.InventLocationIdFrom == inventLocation.InventLocationId
            && inventTransferTable.TransferId == _inventTransferLine.TransferId;

    select firstonly metWHSPhysDimUOMSite
        where metWHSPhysDimUOMSite.ItemId == _inventTransferLine.ItemId
        && metWHSPhysDimUOMSite.SiteId == inventSiteIdFrom
        && metWHSPhysDimUOMSite.UOM == _inventTransferLine.UnitId;

    volume = metWHSPhysDimUOMSite.displayCaseVolumeCM();

    if (metInventLocation.WHSPalletVolume)
    {
        totalPallet = (_shippedQtyInCases * volume) / metInventLocation.WHSPalletVolume;
    }

    return totalPallet;
}

/// <summary>
/// Get WareHouse address By recevingdock role
/// </summary>
/// <param name = "_inventLocationRecId">Location RecId</param>
/// <param name = "_roleRecId">Role Recid</param>
/// <param name = "_type">LogisticsElectronicAddressMethodType</param>
/// <returns>Locator</returns>
private LogisticsEntityPostalAddressView getWareHousePrimaryAddress(RefRecId _inventLocationRecId)
{
    LogisticsEntityPostalAddressView  logisticsEntityPostalAddressView;

    select firstonly Address from logisticsEntityPostalAddressView
        where logisticsEntityPostalAddressView.Entity == _inventLocationRecId
        && logisticsEntityPostalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
        && logisticsEntityPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.IsPrimary == NoYes::Yes;

    return logisticsEntityPostalAddressView;
}
